INSERT INTO `config` VALUES (1, 'resumeTemplateConfig', 'com.abc.resume.config.AppConfig', '{\"modelData\": {\"AWARDS\": {\"LIST\": [{\"date\": \"2023-10\", \"awardsName\": \"全国大学生软件创新大赛\", \"awardsGrade\": \"国家级二等奖\"}, {\"date\": \"2022-09\", \"awardsName\": \"ACM-ICPC 亚洲区域赛\", \"awardsGrade\": \"铜牌\"}, {\"date\": \"2022-06\", \"awardsName\": \"四川大学一等奖学金\", \"awardsGrade\": \"一等奖\"}], \"show\": true, \"model\": \"AWARDS\", \"title\": \"荣誉奖项\", \"isShow\": {\"date\": true, \"awardsName\": true, \"awardsGrade\": true}, \"iconfont\": \"icon-rongyu1\"}, \"HOBBIES\": {\"show\": true, \"model\": \"HOBBIES\", \"style\": {\"mTop\": \"0px\", \"mBottom\": \"45px\", \"textColor\": \"#757575\", \"textFontSize\": \"14px\", \"textFontWeight\": 500}, \"title\": \"兴趣爱好\", \"content\": \"喜欢逛技术博客、阅读开源项目源码、打篮球、跑步，也喜欢通过写博客总结技术问题。\", \"iconfont\": \"icon-xingquaihao\"}, \"BASE_INFO\": {\"age\": 23, \"name\": \"张小明\", \"show\": true, \"email\": \"12322233@qq.com\", \"model\": \"BASE_INFO\", \"title\": \"基本资料\", \"avatar\": \"https://maobucv.com:9000/resume/avatar/file-1663290281512.jpg\", \"degree\": \"本科\", \"isShow\": {\"age\": true, \"email\": true, \"avatar\": true, \"degree\": true, \"address\": true, \"phoneNumber\": true, \"workService\": true}, \"address\": \"四川成都\", \"iconfont\": \"icon-jibenziliao\", \"avatarShape\": \"\", \"phoneNumber\": \"13333333333\", \"workService\": 1}, \"RESUME_TITLE\": {\"show\": true, \"model\": \"RESUME_TITLE\", \"title\": \"我的简历\", \"iconfont\": \"icon-xiangmujingli-04\"}, \"JOB_INTENTION\": {\"show\": true, \"model\": \"JOB_INTENTION\", \"title\": \"求职意向\", \"isShow\": {\"jobStatus\": true, \"expectSalary\": true, \"intendedCity\": true, \"jobSearchType\": true, \"intendedPositions\": true}, \"iconfont\": \"icon-yixianggangwei\", \"jobStatus\": \"随时入职\", \"expectSalary\": \"8000-10000\", \"intendedCity\": \"成都\", \"jobSearchType\": \"全职\", \"intendedPositions\": \"Java开发工程师\"}, \"WORKS_DISPLAY\": {\"LIST\": [{\"worksLink\": \"https://github.com/example/blog-system\", \"worksName\": \"个人博客系统\", \"worksIntroduce\": \"基于 Spring Boot + Vue 开发的个人博客系统，支持文章发布、评论、标签分类、后台管理等功能，使用 Redis 缓存热点数据，提升访问性能。\"}, {\"worksLink\": \"https://github.com/example/cloud-mall\", \"worksName\": \"微服务商城项目\", \"worksIntroduce\": \"基于 Spring Cloud Alibaba 的微服务商城系统，包含商品、订单、用户、支付等模块，使用 Nacos 作为注册中心，Gateway 作为网关，Redis 和 MySQL 做数据存储。\"}], \"show\": true, \"model\": \"WORKS_DISPLAY\", \"title\": \"作品展示\", \"iconfont\": \"icon-zhuanyezhishijineng\"}, \"EDU_BACKGROUND\": {\"LIST\": [{\"date\": [\"2021-09\", \"2025-06\"], \"degree\": \"本科\", \"schoolName\": \"清华大学\", \"majorCourse\": \"计算机组成原理、计算机网络、数据库、前端、后端、移动开发、测试、项目管理\", \"specialized\": \"软件工程\"}], \"show\": true, \"model\": \"EDU_BACKGROUND\", \"title\": \"教育背景\", \"isShow\": {\"date\": true, \"degree\": true, \"schoolName\": true, \"majorCourse\": true, \"specialized\": true}, \"iconfont\": \"icon-education-1-copy\"}, \"SELF_EVALUATION\": {\"show\": true, \"model\": \"SELF_EVALUATION\", \"title\": \"自我评价\", \"content\": \"有较强的责任心和自驱力，能够主动推进问题解决；具备良好的沟通能力和团队协作意识；对新技术保持持续学习热情，习惯通过文档和博客沉淀知识。\", \"iconfont\": \"icon-ziwopingjia\"}, \"WORK_EXPERIENCE\": {\"LIST\": [{\"date\": [\"2021-09\", \"2025-10\"], \"posts\": \"软件开发\", \"jobContent\": \"<ul><li>封装批量查询组件，对多路缓存进行改造，实现对用户、聊天信息等的批量缓存，对查询效率提升 80%</li><li>设计多数据源方案，并结合自动断重连机制，实现服务无感更新，提高了系统的可用性和用户体验</li><li>针对话和消息历史查询，以游标翻页替代传统分页，解决深翻页性能瓶颈，将接口平均响应时间从 500ms 优化至 100ms 内</li></ul>\", \"companyName\": \"腾讯计算机有限公司\"}], \"show\": true, \"model\": \"WORK_EXPERIENCE\", \"title\": \"工作经历\", \"isShow\": {\"date\": true, \"posts\": true, \"companyName\": true}, \"iconfont\": \"icon-gongzuojingyan\"}, \"CAMPUS_EXPERIENCE\": {\"LIST\": [{\"date\": [\"2021-09\", \"2022-10\"], \"campusDuty\": \"技术部部长\", \"campusBriefly\": \"计算机技术协会\", \"campusContent\": \"<ul><li>负责组织技术分享会和编程培训，带领团队完成社团官网开发</li><li>参与策划校园编程比赛，提升社团技术氛围和成员参与度</li></ul>\"}, {\"date\": [\"2022-09\", \"2023-06\"], \"campusDuty\": \"班级学习委员\", \"campusBriefly\": \"软件工程班级\", \"campusContent\": \"<ul><li>协助老师处理日常教学事务，组织同学进行课程复习和项目讨论</li><li>反馈学习问题，促进班级学习氛围</li></ul>\"}], \"show\": true, \"model\": \"CAMPUS_EXPERIENCE\", \"title\": \"校园经历\", \"isShow\": {\"date\": true, \"campusDuty\": true, \"campusBriefly\": true, \"campusContent\": true}, \"iconfont\": \"icon-jiatimianban_timu\"}, \"SKILL_SPECIALTIES\": {\"show\": true, \"model\": \"SKILL_SPECIALTIES\", \"title\": \"专业技能\", \"content\": \"<ul><li>熟练掌握 Java 基础，对集合、多线程、Stream 流有一定了解</li><li>熟悉使用 SSM、SpringBoot、Mybatis 等主流开源框架，了解 IOC、AOP、Bean 生命周期等</li><li>熟练掌握 MySQL 数据库，对索引、事务、锁、MVCC 与 SQL 优化有一定了解</li><li>熟悉使用 Redis 数据库，了解缓存穿透、击穿、雪崩等问题，了解缓存一致性解决方案，了解分布式锁的实现</li><li>熟悉使用 Git、Maven、Postman、Jmeter 等工具，熟悉 Linux 系统常用命令，能够独立部署项目</li><li>熟悉 Nginx、Docker，消息队列 RabbitMQ 的使用，能够使用 Docker 部署项目中间件</li><li>熟悉 JVM，比如：内存区域、类加载过程、双亲委派机制、垃圾回收等</li><li>了解 SpringCloud 相关微服务组件，比如：Nacos 服务注册与发现，OpenFeign 远程调用等</li><li>了解常用的设计模式，如单例模式、策略模式、模板方法模式和工厂模式等</li></ul>\", \"iconfont\": \"icon-zhuanyezhishijineng\"}, \"PROJECT_EXPERIENCE\": {\"LIST\": [{\"date\": [\"2021-09\", \"2022-10\"], \"posts\": \"前后端开发\", \"projectName\": \"仿CSDN平台\", \"projectContent\": \"<ul><li>文章详情页静态分离，采用 Thymeleaf 对文章页面静态化处理，上传至 Minio 中并通过 Nginx 代理访问，降低了对象服务器资源的消耗</li><li>支付文章购买整合支付宝沙箱支付，通过消息队列 + 本地事务表实现支付回调异步处理与权益发放，基于最终一致性保证订单与用户权限数据同步</li><li>采用 Cookie 与 Token 验证机制实现单点登录，统一登录态存储与校验逻辑</li></ul>\"}, {\"date\": [\"2023-03\", \"2023-09\"], \"posts\": \"后端开发\", \"projectName\": \"苍穹外卖\", \"projectContent\": \"<ul><li>参与菜品管理、订单管理、购物车、用户登录等模块开发</li><li>使用 Spring Boot + MyBatis-Plus + Redis + MySQL 实现核心业务</li><li>使用 JWT 完成登录鉴权，使用 WebSocket 实现来单提醒</li></ul>\"}], \"show\": true, \"model\": \"PROJECT_EXPERIENCE\", \"title\": \"项目经历\", \"isShow\": {\"date\": true, \"posts\": true, \"projectName\": true}, \"iconfont\": \"icon-xiangmu\"}, \"INTERNSHIP_EXPERIENCE\": {\"LIST\": [{\"date\": [\"2024-09\", \"至今\"], \"posts\": \"后端工程师（实习）\", \"jobContent\": \"<ul><li>文章详情页静态分离，采用 Thymeleaf 对文章页面静态化处理，上传至 Minio 中并通过 Nginx 代理访问，降低了对象服务器资源的消耗</li><li>支付文章购买整合支付宝沙箱支付，通过消息队列 + 本地事务表实现支付回调异步处理与权益发放，基于最终一致性保证订单与用户权限数据同步</li><li>采用 Cookie 与 Token 验证机制实现单点登录，统一登录态存储与校验逻辑</li><li>使用 Redis + Lua 脚本实现对用户优惠券的秒杀资格的预检，用 RabbitMQ 消息队列对减库存等操作进行异步解耦和削峰填谷，同时用乐观锁解决秒杀产生的超卖问题</li><li>封装 AI 框架，搭建 RAG 知识文档，提升站内搜索的准确性与参考价</li></ul>\", \"companyName\": \"领锐科技（成都）有限公司\"}], \"show\": true, \"model\": \"INTERNSHIP_EXPERIENCE\", \"title\": \"实习经历\", \"isShow\": {\"date\": true, \"posts\": true, \"jobContent\": true, \"companyName\": true}, \"iconfont\": \"icon-biyeshixi\"}}, \"modelStyle\": {\"AWARDS\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"HOBBIES\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"BASE_INFO\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"5px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"RESUME_TITLE\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"JOB_INTENTION\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"WORKS_DISPLAY\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"EDU_BACKGROUND\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"SELF_EVALUATION\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"WORK_EXPERIENCE\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"CAMPUS_EXPERIENCE\": {\"mTop\": \"0px\", \"pTop\": \"12