INSERT INTO `resume_template` VALUES (4, 'side', '双栏模板', '蓝色侧栏放照片与联系方式，右栏主题色下划线小标题配两行条目头，适合内容较多的简历', 'https://www.jixer.top/system/oss/download/4', 1, '{\"style\": {\"pTop\": \"12px\", \"pBottom\": \"0px\", \"leftWidth\": \"25%\", \"pLeftRight\": \"26px\", \"themeColor\": \"#850e32\", \"titleStyle\": \"underlineTitle\", \"textFontSize\": \"12px\", \"textFontColor\": \"#444444\", \"leftThemeColor\": \"#4184ff\", \"modelMarginTop\": \"0px\", \"textFontWeight\": 400, \"rightThemeColor\": \"\", \"secondTitleColor\": \"#000000\", \"modelMarginBottom\": \"0px\", \"secondTitleWeight\": 600, \"firstTitleFontSize\": \"15px\", \"resumeBackgroundCom\": \"\", \"secondTitleFontSize\": \"13px\"}, \"hidden\": [\"RESUME_TITLE\", \"INTERNSHIP_EXPERIENCE\", \"HOBBIES\", \"WORKS_DISPLAY\", \"CAMPUS_EXPERIENCE\", \"AWARDS\"], \"layout\": \"leftRight\", \"columns\": {\"left\": [\"BASE_INFO\", \"JOB_INTENTION\"], \"right\": [\"EDU_BACKGROUND\", \"SKILL_SPECIALTIES\", \"CAMPUS_EXPERIENCE\", \"WORK_EXPERIENCE\", \"PROJECT_EXPERIENCE\", \"AWARDS\", \"SELF_EVALUATION\"]}, \"variants\": {\"AWARDS\": \"AWARDS_1\", \"HOBBIES\": \"HOBBIES_1\", \"BASE_INFO\": \"BASE_INFO_3\", \"JOB_INTENTION\": \"JOB_INTENTION_2\", \"WORKS_DISPLAY\": \"WORKS_DISPLAY_1\", \"EDU_BACKGROUND\": \"EDU_BACKGROUND_1\", \"SELF_EVALUATION\": \"SELF_EVALUATION_1\", \"WORK_EXPERIENCE\": \"WORK_EXPERIENCE_2\", \"CAMPUS_EXPERIENCE\": \"CAMPUS_EXPERIENCE_2\", \"SKILL_SPECIALTIES\": \"SKILL_SPECIALTIES_1\", \"PROJECT_EXPERIENCE\": \"PROJECT_EXPERIENCE_2\", \"INTERNSHIP_EXPERIENCE\": \"INTERNSHIP_EXPERIENCE_1\"}}', 1, 0, '2026-09-29 12:00:00', '2026-09-29 17:20:51', 1, 1, 0);

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户ID',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '昵称',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '账号',
  `password` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '密码',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '头像',
  `openid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'openid',
  `ch` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `status` tinyint NOT NULL COMMENT '状态',
  `ver` int NOT NULL COMMENT '版本号',
  `is_delete` bigint NOT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_user_username_ch`(`username` ASC, `ch` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户表' ROW_FORMAT = DYNAMIC;

