-- ----------------------------
-- Table structure for user_resume
-- ----------------------------
DROP TABLE IF EXISTS `user_resume`;
CREATE TABLE `user_resume`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户ID',
  `resume_detail` json NULL COMMENT '简历详情',
  `thumbnail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '缩略图地址，未生成时为空串',
  `template_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '模板编码',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `status` int NOT NULL DEFAULT 1 COMMENT '数据状态：1=正常 2=禁用',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `ver` int NOT NULL DEFAULT 0 COMMENT '版本号',
  `is_delete` bigint NOT NULL COMMENT '软删标记',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_resume_user`(`uid` ASC, `is_delete` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户简历表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of user_resume
-- ----------------------------
INSERT INTO `user_resume` VALUES (1, '2vBhIVdHF6g', '{\"NAME\": \"Java开发黎俊熙\", \"TITLE\": null, \"LAYOUT\": \"classical\", \"COMPONENTS\": [{\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"age\": 23, \"name\": \"张小明\", \"show\": true, \"email\": \"12322233@qq.com\", \"model\": \"BASE_INFO\", \"title\": \"基本资料\", \"avatar\": \"https://www.jixer.top/system/oss/download/6\", \"degree\": \"本科\", \"isShow\": {\"age\": true, \"email\": true, \"avatar\": true, \"degree\": true, \"address\": true, \"phoneNumber\": true, \"workService\": true}, \"address\": \"四川成都\", \"iconfont\": \"icon-jibenziliao\", \"avatarShape\": \"\", \"phoneNumber\": \"13333333333\", \"workService\": 1}, \"show\": true, \"keyId\": \"2vBhXNT7yWk\", \"model\": \"BASE_INFO\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"avatarWidth\": \"84px\", \"avatarHeight\": \"100px\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"BASE_INFO_1\", \"cptTitle\": \"基础资料\", \"cptWidth\": \"100%\", \"cptHeight\": \"100px\", \"cptOptionsName\": \"BASE_INFO_OPTIONS\"}, {\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"LIST\": [{\"date\": [\"2021-09\", \"2025-06\"], \"degree\": \"本科\", \"schoolName\": \"清华大学\", \"majorCourse\": \"计算机组成原理、计算机网络、数据库、前端、后端、移动开发、测试、项目管理\", \"specialized\": \"软件工程\"}], \"show\": true, \"model\": \"EDU_BACKGROUND\", \"title\": \"教育背景\", \"isShow\": {\"date\": true, \"degree\": true, \"schoolName\": true, \"majorCourse\": true, \"specialized\": true}, \"iconfont\": \"icon-education-1-copy\"}, \"show\": true, \"keyId\": \"2vBhXNTpa4o\", \"model\": \"EDU_BACKGROUND\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"EDU_BACKGROUND_1\", \"cptTitle\": \"教育背景\", \"cptWidth\": \"100%\", \"cptHeight\": \"100px\", \"cptOptionsName\": \"EDU_BACKGROUND_OPTIONS\"}, {\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"show\": true, \"model\": \"SKILL_SPECIALTIES\", \"title\": \"专业技能\", \"content\": \"<ul><li>熟练掌握 Java 基础，对集合、多线程、Stream 流有一定了解</li><li>熟悉使用 SSM、SpringBoot、Mybatis 等主流开源框架，了解 IOC、AOP、Bean 生命周期等</li><li>熟练掌握 MySQL 数据库，对索引、事务、锁、MVCC 与 SQL 优化有一定了解</li><li>熟悉使用 Redis 数据库，了解缓存穿透、击穿、雪崩等问题，了解缓存一致性解决方案，了解分布式锁的实现</li><li>熟悉使用 Git、Maven、Postman、Jmeter 等工具，熟悉 Linux 系统常用命令，能够独立部署项目</li><li>熟悉 Nginx、Docker，消息队列 RabbitMQ 的使用，能够使用 Docker 部署项目中间件</li><li>熟悉 JVM，比如：内存区域、类加载过程、双亲委派机制、垃圾回收等</li><li>了解 SpringCloud 相关微服务组件，比如：Nacos 服务注册与发现，OpenFeign 远程调用等</li><li>了解常用的设计模式，如单例模式、策略模式、模板方法模式和工厂模式等</li></ul>\", \"iconfont\": \"icon-zhuanyezhishijineng\"}, \"show\": true, \"keyId\": \"2vBhXNTpa4p\", \"model\": \"SKILL_SPECIALTIES\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"SKILL_SPECIALTIES_1\", \"cptTitle\": \"专业技能\", \"cptWidth\": \"100%\", \"cptHeight\": \"50px\", \"cptOptionsName\": \"SKILL_SPECIALTIES_OPTIONS\"}, {\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"LIST\": [{\"date\": [\"2021-09\", \"至今\"], \"posts\": \"软件开发\", \"department\": \"\", \"jobContent\": \"<ul><li>封装批量查询组件，对多路缓存进行改造，实现对用户、聊天信息等的批量缓存，对查询效率提升 80%</li><li>设计多数据源方案，并结合自动断重连机制，实现服务无感更新，提高了系统的可用性和用户体验</li><li>针对话和消息历史查询，以游标翻页替代传统分页，解决深翻页性能瓶颈，将接口平均响应时间从 500ms 优化至 100ms 内</li></ul>\", \"companyName\": \"腾讯计算机有限公司\"}], \"show\": true, \"model\": \"WORK_EXPERIENCE\", \"title\": \"工作经历\", \"isShow\": {\"date\": true, \"posts\": true, \"companyName\": true}, \"iconfont\": \"icon-gongzuojingyan\"}, \"show\": true, \"keyId\": \"2vBhXNTpa4q\", \"model\": \"WORK_EXPERIENCE\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"WORK_EXPERIENCE_1\", \"cptTitle\": \"工作经验\", \"cptWidth\": \"100%\", \"cptHeight\": \"50px\", \"cptOptionsName\": \"WORK_EXPERIENCE_OPTIONS\"}, {\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"LIST\": [{\"date\": [\"2021-09\", \"2022-10\"], \"posts\": \"前后端开发\", \"projectName\": \"仿CSDN平台\", \"projectContent\": \"<ul><li>文章详情页静态分离，采用 Thymeleaf 对文章页面静态化处理，上传至 Minio 中并通过 Nginx 代理访问，降低了对象服务器资源的消耗</li><li>支付文章购买整合支付宝沙箱支付，通过消息队列 + 本地事务表实现支付回调异步处理与权益发放，基于最终一致性保证订单与用户权限数据同步</li><li>采用 Cookie 与 Token 验证机制实现单点登录，统一登录态存储与校验逻辑</li></ul>\"}, {\"date\": [\"2023-03\", \"2023-09\"], \"posts\": \"后端开发\", \"projectName\": \"苍穹外卖\", \"projectContent\": \"<ul><li>参与菜品管理、订单管理、购物车、用户登录等模块开发</li><li>使用 Spring Boot + MyBatis-Plus + Redis + MySQL 实现核心业务</li><li>使用 JWT 完成登录鉴权，使用 WebSocket 实现来单提醒</li></ul>\"}], \"show\": true, \"model\": \"PROJECT_EXPERIENCE\", \"title\": \"项目经历\", \"isShow\": {\"date\": true, \"posts\": true, \"projectName\": true}, \"iconfont\": \"icon-xiangmu\"}, \"show\": true, \"keyId\": \"2vBhXNTGLcs\", \"model\": \"PROJECT_EXPERIENCE\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"PROJECT_EXPERIENCE_1\", \"cptTitle\": \"项目经验\", \"cptWidth\": \"100%\", \"cptHeight\": \"50px\", \"cptOptionsName\": \"PROJECT_EXPERIENCE_OPTIONS\"}, {\"cptX\": 0, \"cptY\": 0, \"cptZ\": 0, \"data\": {\"show\": true, \"model\": \"SELF_EVALUATION\", \"title\": \"自我评价\", \"content\": \"有较强的责任心和自驱力，能够主动推进问题解决；具备良好的沟通能力和团队协作意识；对新技术保持持续学习热情，习惯通过文档和博客沉淀知识。\", \"iconfont\": \"icon-ziwopingjia\"}, \"show\": true, \"keyId\": \"2vBhXNTGLct\", \"model\": \"SELF_EVALUATION\", \"style\": {\"mTop\": \"0px\", \"pTop\": \"12px\", \"mBottom\": \"0px\", \"pBottom\": \"0px\", \"textColor\": \"#4b5563\", \"pLeftRight\": \"48px\", \"themeColor\": \"#2b74ff\", \"titleColor\": \"#121c26\", \"textFontSize\": \"13px\", \"titleFontSize\": \"13px\", \"textFontWeight\": 400, \"backgroundColor\": \"\", \"titleFontWeight\": 600, \"firstTitleFontSize\": \"16px\"}, \"layout\": \"\", \"cptName\": \"SELF_EVALUATION_1\", \"cptTitle\": \"自我评价\", \"cptWidth\": \"100%\", \"cptHeight\": \"50px\", \"cptOptionsName\": \"SELF_EVALUATION_OPTIONS\"}], \"GLOBAL_STYLE\": {\"ptop\": \"12px\", \"pbottom\": \"0px\", \"leftWidth\": \"\", \"fontFamily\": null, \"pleftRight\": \"48px\", \"rightWidth\": \"\", \"themeColor\": \"#2b74ff\", \"textFontSize\": \"13px\", \"textFontColor\": \"#4b5563\", \"leftThemeColor\": \"\", \"modelMarginTop\": \"0px\", \"textFontWeight\": 400, \"rightThemeColor\": \"\", \"secondTitleColor\": \"#121c26\", \"modelMarginBottom\": \"0px\", \"secondTitleWeight\": 600, \"firstTitleFontSize\": \"16px\", \"resumeBackgroundCom\": \"\", \"secondTitleFontSize\": \"13px\"}}', '', 'classic', '2026-10-03 22:25:48', 1, '2026-10-03 22:40:04', 4, 1791037548183);

